const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');
if (product !== 'sos') throw new Error('unsupported_product');
if (resource !== 'dispatch') throw new Error('unsupported_resource');
const recordId = text(fields.order_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(recordId)) throw new Error('record_id_invalid');
const encodedId = encodeURIComponent(recordId);
const allowed = new Set(["order_id"]);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));

const patch = { status: 'canceled' };
const audit = {
  product, resource, operation: 'dispatch.reject', recordId,
  pluginId: text(envelope.pluginId), widgetId: text(envelope.widgetId),
  submittedBy, submittedAt: text(envelope.submittedAt) || $now,
};

return { recordId, encodedId, patch, audit, operation: 'dispatch.reject' };

const response = $input || {};
const current = response.body;
const action = response.input;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('record_not_found');
const data = current.data;
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
if (['completed', 'canceled', 'rejected'].includes(String(data.status))) throw new Error('record_terminal');
if (!["pending","assigned"].includes(String(data.status))) throw new Error('record_status_invalid');
const next = { ...data, ...action.patch };
return { body: { data: next, ifVersion: current.version }, encodedId: action.encodedId, audit: action.audit, operation: action.operation };
